#!/usr/bin/env python3
import re

ID_RE = re.compile(r'^ORD-([0-9A-Z]{4})$')

def main():
    # Read ids.txt, most recent id is the last non-empty line
    last_id = None
    with open('ids.txt') as f:
        for line in f:
            line = line.strip()
            if line:
                last_id = line

    if last_id is None:
        # No ids yet; start from zero
        next_val = 0
    else:
        m = ID_RE.match(last_id)
        if not m:
            raise ValueError(f"Invalid id format: {last_id}")
        suffix = m.group(1)
        next_val = int(suffix, 36) + 1

    # Format as 4-character zero-padded base-36
    def to_base36(n):
        chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        result = ''
        for _ in range(4):
            result = chars[n % 36] + result
            n //= 36
        return result

    print(f"ORD-{to_base36(next_val)}")

if __name__ == '__main__':
    main()

